/* LocationPurgeMapper.purgeAttdGpsByUser */
UPDATE TB_USER_ATTD_GPS
   SET LAT     = NULL
     , LON     = NULL
     , LAT_ENC = NULL
     , LON_ENC = NULL
 WHERE CMPNY_CD = #{cmpnyCd}
   AND USER_CD = #{userCd}
   AND (LAT IS NOT NULL OR LON IS NOT NULL OR LAT_ENC IS NOT NULL OR LON_ENC IS NOT NULL)

/* LocationPurgeMapper.purgeTbmAttendanceGpsByUser */
UPDATE TB_TBM_ATTENDANCE
   SET ENTRY_GPS_LAT     = NULL
     , ENTRY_GPS_LON     = NULL
     , ENTRY_GPS_LAT_ENC = NULL
     , ENTRY_GPS_LON_ENC = NULL
 WHERE CMPNY_CD = #{cmpnyCd}
   AND USER_CD = #{userCd}
   AND USER_TYPE_CD = #{userTypeCd}
   AND (ENTRY_GPS_LAT IS NOT NULL OR ENTRY_GPS_LON IS NOT NULL
        OR ENTRY_GPS_LAT_ENC IS NOT NULL OR ENTRY_GPS_LON_ENC IS NOT NULL)

/* LocationPurgeMapper.purgeTbmSessionGpsByUser */
UPDATE TB_TBM_SESSION
   SET MANAGER_GPS_LAT     = NULL
     , MANAGER_GPS_LON     = NULL
     , MANAGER_GPS_LAT_ENC = NULL
     , MANAGER_GPS_LON_ENC = NULL
 WHERE CMPNY_CD = #{cmpnyCd}
   AND MANAGER_USER_CD = #{userCd}
   AND (MANAGER_GPS_LAT IS NOT NULL OR MANAGER_GPS_LON IS NOT NULL
        OR MANAGER_GPS_LAT_ENC IS NOT NULL OR MANAGER_GPS_LON_ENC IS NOT NULL)

mapper.insert:
/* LocationPurgeMapper.insertPurgeHist */
INSERT INTO TB_LOCATION_PURGE_HIST (
      CMPNY_CD
    , USER_CD
    , USER_TYPE_CD
    , PURGE_REASON_CD
    , TERMS_VERSION
    , ATTD_GPS_ROWS
    , TBM_ATTENDANCE_ROWS
    , TBM_SESSION_ROWS
    , OLDEST_COLLECTED
    , LATEST_COLLECTED
    , ACTOR_CMPNY_CD
    , ACTOR_USER_CD
    , ACTION_DTIME
    , INSERT_NO
    , INSERT_DATE
) VALUES (
      #{cmpnyCd}
    , #{userCd}
    , #{userTypeCd}
    , #{purgeReasonCd}
    , #{termsVersion}
    , #{attdGpsRows}
    , #{tbmAttendanceRows}
    , #{tbmSessionRows}
    , #{oldestCollected}
    , #{latestCollected}
    , #{actorCmpnyCd}
    , #{actorUserCd}
    , NOW()
    , #{actorUserCd}
    , NOW()
)
